9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const satisfies Record<string, number>;
17	
18	type InsurableItemType = keyof typeof BASE_PREMIUMS;
19	
20	type Item = {
21	  type: InsurableItemType;
22	  material?: string;
23	  enchantment?: number;
24	  cursed?: boolean;
25	};
26	
27	type QuoteStep = {
28	  op: "quote";
29	  items: Item[];
30	};
31	
32	type Customer = {
33	  yearsWithMHPCO: number;
34	};
35	
36	type Scenario = {
