39	};
40	
41	const PROCESSING_FEE = 5;
42	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
43	const CURSE_SURCHARGE_PERCENT = 50;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
46	const LOYALTY_THRESHOLD_YEARS = 2;
47	const LOYALTY_DISCOUNT_PERCENT = 20;
48	
49	const percentOf = (amount: number, percent: number): number =>
50	  (amount * percent) / 100;
51	
52	// The MHPCO always rounds in its own favour: premiums (which the customer
53	// pays) go up. Payouts round down, but no test demands that yet.
54	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
55	
56	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
57	
58	// Exactly this many components of the same type form a "building block",
59	// priced as a unit rather than per item.
60	const BUILDING_BLOCK_SIZE = 3;
61	const BUILDING_BLOCK_BASE_PREMIUM = 60;
62	
63	const sumOf = (amounts: number[]): number =>
64	  amounts.reduce((total, amount) => total + amount, 0);
65	
66	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
67	
68	const alikeItemGroups = (items: Item[]): Item[][] =>
69	  insurableItemTypes
70	    .map((type) => items.filter((item) => item.type === type))
71	    .filter((alikeItems) => alikeItems.length > 0);
72	
73	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
74	  alikeItems.length === BUILDING_BLOCK_SIZE;
75	
76	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
77	  formsBuildingBlock(alikeItems)
78	    ? BUILDING_BLOCK_BASE_PREMIUM
79	    : sumOf(alikeItems.map(itemBasePremiumOf));
80	
81	const policyBasePremiumOf = (items: Item[]): number =>
82	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
83	
84	const isCursed = (item: Item): boolean => item.cursed === true;
85	
86	const isHighlyEnchanted = (item: Item): boolean =>
87	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
88	
89	// Each surcharge is a percentage of the base premium of the item that
90	// triggers it. Surcharges are cumulative: every applicable one is added.
91	type ItemSurcharge = {
92	  appliesTo: (item: Item) => boolean;
93	  percent: number;
94	};
95	
96	const ITEM_SURCHARGES: ItemSurcharge[] = [
97	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
98	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
99	];
100	
101	// Item-specific modifiers apply to the base premium of the affected item.
102	const itemModifiersOf = (item: Item): number =>
103	  sumOf(
104	    ITEM_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)).map(
105	      (surcharge) => percentOf(itemBasePremiumOf(item), surcharge.percent),
106	    ),
107	  );
108	
109	const isLongStanding = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
111	
112	const quote = (step: QuoteStep, customer: Customer): QuoteResult => {
113	  const policyBasePremium = policyBasePremiumOf(step.items);
114	  const itemModifiers = sumOf(step.items.map(itemModifiersOf));
115	  const initialAssessmentSurcharge = percentOf(
116	    policyBasePremium,
117	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
118	  );
119	  const loyaltyDiscount = isLongStanding(customer)
120	    ? percentOf(policyBasePremium, LOYALTY_DISCOUNT_PERCENT)
121	    : 0;
122	
123	  return {
124	    premium: roundedUpInMHPCOsFavour(
125	      policyBasePremium +
126	        itemModifiers +
127	        initialAssessmentSurcharge -
128	        loyaltyDiscount +
129	        PROCESSING_FEE,
130	    ),
131	  };
132	};
133	
134	export const runScenario = (scenario: Scenario): ScenarioResult => {
135	  return {
136	    results: scenario.steps.map((step) => quote(step, scenario.customer)),
137	  };
138	};
