input.new_string:
const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;

// Each policy-wide modifier is a percentage of the policy base premium.
// A surcharge has a positive percent, a discount a negative one, so they all
// combine by summing. Modifiers are cumulative: every applicable one applies.
type PolicyModifier = {
  appliesTo: (customer: Customer) => boolean;
  percent: number;
};

const alwaysApplies = (): boolean => true;

const POLICY_MODIFIERS: PolicyModifier[] = [
  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
  { appliesTo: isLongStanding, percent: -LOYALTY_DISCOUNT_PERCENT },
];

const policyModifiersOf = (
  policyBasePremium: number,
  customer: Customer,
): number =>
  sumOf(
    POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(customer)).map(
      (modifier) => percentOf(policyBasePremium, modifier.percent),
    ),
  );

const quote = (step: QuoteStep, customer: Customer): QuoteResult => {
  const policyBasePremium = policyBasePremiumOf(step.items);
  const itemModifiers = sumOf(step.items.map(itemModifiersOf));
  const policyModifiers = policyModifiersOf(policyBasePremium, customer);

  return {
    premium: roundedUpInMHPCOsFavour(
      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
    ),
  };
};
